BASE=Path(__file__).parent
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='DocTitle',fontName='Helvetica-Bold',fontSize=22,leading=26,textColor=colors.HexColor('#24384F'),spaceAfter=10))
styles.add(ParagraphStyle(name='Step',fontName='Helvetica-Bold',fontSize=14,leading=18,textColor=colors.HexColor('#24384F'),spaceBefore=17,spaceAfter=9))
styles.add(ParagraphStyle(name='Explain',fontName='Helvetica',fontSize=11,leading=16,spaceAfter=9))
